def process_orders(orders):
    if not orders:
        return []
    out = []
    for order in orders:
        amount = order.get('amount', 0)
        payment = order.get('payment')
        validator = getattr(payment, 'validate', None)
        if amount > 0 and callable(validator) and validator(order):
            oid = order.get('id')
            if oid is not None:
                out.append(oid)
    return out
